// AgentConfigFile defines model for AgentConfigFile.
type AgentConfigFile struct {
	// Mode 文件权限（十进制表示的 Unix 权限位）
	Mode int    `json:"mode"`
	Path string `json:"path"`

	// Sha256 SHA-256 小写十六进制
	Sha256 Sha256 `json:"sha256"`
	Size   int64  `json:"size"`

	// UpdatedAt UTC 毫秒时间戳
	UpdatedAt TimestampMs `json:"updatedAt"`
}

// AgentConfigFileList defines model for AgentConfigFileList.
type AgentConfigFileList struct {
	Files []AgentConfigFile `json:"files"`
}

// AgentConfigImportResult defines model for AgentConfigImportResult.
type AgentConfigImportResult struct {
	ExtractedSecrets []string             `json:"extractedSecrets"`
	Files            []AgentConfigFile    `json:"files"`
	Warnings         []AgentConfigWarning `json:"warnings"`
}

// AgentConfigWarning defines model for AgentConfigWarning.
type AgentConfigWarning struct {
	// Kind `possible_secret`（非 models.yml 文件中形似密钥的串）、`env_fallback`（provider 走环境变量降级）等
	Kind    string `json:"kind"`
	Line    *int   `json:"line,omitempty"`
	Message string `json:"message"`
	Path    string `json:"path"`
}

// AgentConfigWriteResult defines model for AgentConfigWriteResult.
type AgentConfigWriteResult struct {
	// ExtractedSecrets 本次从 models.yml 抽取进密钥库的密钥名
	ExtractedSecrets []string             `json:"extractedSecrets"`
	File             AgentConfigFile      `json:"file"`
	Warnings         []AgentConfigWarning `json:"warnings"`
}

// AgentLiveState 线程实时缓冲（只含未被条目覆盖的部分）
type AgentLiveState struct {
	// Live 在途消息（`openMessage`）与运行中工具（`openTools`）的帧，按到达顺序
	Live []OmpFrame `json:"live"`

	// PendingUI 未应答的 `extension_ui_request` 帧
	PendingUI []OmpFrame `json:"pendingUi"`

	// PlanProposal 未决的 `plan_proposal` 帧
	PlanProposal *OmpFrame `json:"planProposal,omitempty"`

	// Queue 最新 `queue_update` 帧
	Queue *OmpFrame `json:"queue,omitempty"`

	// State 最近一次 `get_state` 应答的 data
	State *OmpFrame `json:"state,omitempty"`

	// Status 线程 agent 进程状态；`none` = 尚未启动或 orb 不可用
	Status AgentStatus `json:"status"`

	// Subagents 各子 agent 最新的 `subagent_lifecycle` / `subagent_progress` 帧
	Subagents []OmpFrame `json:"subagents"`
}

// AgentStatus 线程 agent 进程状态；`none` = 尚未启动或 orb 不可用
type AgentStatus string

// AppSessionCode App 会话一次性码（M6）；以 `GET /auth/app?code=…&next=…` 兑换
type AppSessionCode struct {
	// Code `oac_…`，只能兑换一次
	Code string `json:"code"`

	// ExpiresIn 有效秒数
	//
	// Example: 30
	ExpiresIn int `json:"expiresIn"`
}

// Attachment defines model for Attachment.
type Attachment struct {
	// CreatedAt UTC 毫秒时间戳
	CreatedAt TimestampMs `json:"createdAt"`

	// ID `att_<ulid>`
	ID   AttachmentID `json:"id"`
	Mime string       `json:"mime"`

	// Name 净化后的文件名（≤200 字节）
	Name string `json:"name"`

	// PublicURL 已发布时的公开 URL（`<public_url>/f/<slug>/<文件名>`）；未发布省略
	PublicURL *string `json:"publicUrl,omitempty"`

	// Sha256 SHA-256 小写十六进制
	Sha256 Sha256 `json:"sha256"`
	Size   int64  `json:"size"`

	// ThreadID 绑定的线程；尚未绑定时省略
	ThreadID *ThreadID `json:"threadId,omitempty"`
}

// AttachmentID `att_<ulid>`
type AttachmentID = string

// AttachmentList defines model for AttachmentList.
type AttachmentList struct {
	Attachments []Attachment `json:"attachments"`
}

